/* PyTrail curriculum data. Examples are authored for this project and are runnable in the browser runtime unless noted. */
(function () {
  const L = (id, title, intro, code, output, walkthrough, challenge, starter, expected, hint1, hint2, solution, mistakes = 'Check spelling, indentation, quotation marks, and the type of each value. Read the traceback from the bottom upward first.') => ({
    id, title, intro, code, output, walkthrough, challenge, starter, expected, hint1, hint2, solution, mistakes,
    objectives: [`Explain the purpose of ${title.toLowerCase()}.`, 'Read and modify a working Python example.', 'Use the concept in a small independent task.'],
    minutes: 10 + (title.length % 7), difficulty: 'Beginner'
  });
  const modules = [
    {id:'start',number:0,title:'Getting Started',subtitle:'Meet Python and write your first program.',level:'Beginner',icon:'✦',topics:['What programming is','What Python is used for','How Python runs code','Python source files and .py files','Python versus HTML, CSS, and JavaScript','The interpreter and code editors','Running a script in a terminal','Local Python versus browser Python','Your first program','Common beginner misconceptions'],lessons:[
      L('hello-world','Your first Python program','Python follows instructions from top to bottom. `print()` sends text to the output stream, so it is the easiest way to see what your program is doing. You can experiment immediately in the playground without installing Python.', 'print("Hello, world!")\nprint("I am learning Python.")', 'Hello, world!\nI am learning Python.', '`print()` is a built-in function. Parentheses contain the value you want to display. Text is written inside matching quotation marks. Each call prints a line by default.', 'Print your name and one reason you want to learn Python.', 'print("My name is ...")\nprint("I want to learn Python because ...")', 'Replace the dots with your own words. The output should show two lines.', 'Keep each message inside quotation marks.', 'Use a second `print()` call for the second line.', 'print("My name is Alex")\nprint("I want to build useful programs")'),
      L('how-python-runs','How Python runs code','A Python program is a sequence of statements. The Python implementation reads each statement and performs its work. In this browser academy, Pyodide runs CPython compiled to WebAssembly; that is different from installing a local Python interpreter on Windows.', 'price = 12\nquantity = 3\ntotal = price * quantity\nprint(total)', '36', 'The first two lines assign values to names. The third calculates a result and stores it in `total`. The final statement displays that result. Order matters: a name must normally be assigned before it is used.', 'Create `minutes` and `hours` variables, calculate the number of minutes in those hours, and print it.', 'hours = 2\n# create minutes and print it', 'The result for two hours should be 120.', 'Multiply the number of hours by 60.', 'Store the multiplication result in a variable before printing.', 'hours = 2\nminutes = hours * 60\nprint(minutes)'),
      L('python-vs-web','Python, HTML, CSS, and JavaScript','HTML describes page structure, CSS controls presentation, JavaScript handles browser interactions, and Python is a general-purpose programming language. Different languages can work together, but their jobs and runtimes are not interchangeable.', 'language = "Python"\nuse = "data, automation, scripting, and more"\nprint(f"{language} can help with {use}.")', 'Python can help with data, automation, scripting, and more.', 'The `f` before the string enables an f-string. Expressions inside braces are replaced by their values. F-strings are useful for clear messages that combine text and variables.', 'Use an f-string to display a tool and one thing it can help you do.', 'tool = "Python"\njob = "..."\nprint(f"{tool} can help me {job}.")', 'Your output should contain both variable values.', 'Put an `f` immediately before the opening quote.', 'Place variable names inside `{}` within the string.', 'tool = "Python"\njob = "organize files"\nprint(f"{tool} can help me {job}.")')
    ]},
    {id:'fundamentals',number:1,title:'Python Fundamentals',subtitle:'Values, variables, input, and everyday calculations.',level:'Beginner',icon:'⌁',topics:['print()','Comments','Variables and naming conventions','Identifiers','Strings, integers, floats, and booleans','Arithmetic operators','/, //, %, and **','Operator precedence','type()','input()','int(), float(), and str()','Basic output formatting','Common syntax mistakes'],lessons:[
      L('variables-types','Variables and data types','A variable is a name that refers to a value. Python does not require you to declare a variable type first: the value assigned determines the current type. Use meaningful names such as `score` rather than unclear names such as `x` for every task.', 'player_name = "Mina"\nscore = 42\nis_ready = True\nprint(player_name)\nprint(score)\nprint(type(is_ready).__name__)', 'Mina\n42\nbool', '`=` assigns a value; it does not test equality. Strings hold text, integers hold whole numbers, floats hold decimal numbers, and booleans represent `True` or `False`. Names are case-sensitive.', 'Create variables for a book title, the number of pages, and whether you have finished it. Print each value.', 'title = "..."\npages = ...\nfinished = ...\nprint(title, pages, finished)', 'Use a string, an integer, and a boolean.', 'Choose a value with the correct type for each variable.', 'Python boolean values are capitalized: `True` and `False`.', 'title = "The Python Book"\npages = 240\nfinished = False\nprint(title, pages, finished)'),
      L('math-operators','Arithmetic and operator precedence','Python supports addition, subtraction, multiplication, division, floor division, remainder, and exponentiation. Parentheses make your intended order clear. `/` always produces a floating-point result, while `//` rounds the quotient down to an integer-like floor result.', 'print(7 + 3)\nprint(7 / 2)\nprint(7 // 2)\nprint(7 % 2)\nprint(2 ** 4)\nprint((2 + 3) * 4)', '10\n3.5\n3\n1\n16\n20', '`%` returns a remainder and is useful for checking divisibility. `**` raises a number to a power. Python evaluates exponentiation before multiplication and multiplication before addition, unless parentheses change the order.', 'Calculate how many full boxes of 6 fit 29 items and how many items remain.', 'items = 29\nbox_size = 6\nfull_boxes = ...\nleftover = ...\nprint(full_boxes, leftover)', 'The answer should be 4 full boxes and 5 leftover items.', 'Use floor division to get the full number of boxes.', 'Use the remainder operator for the items left over.', 'items = 29\nbox_size = 6\nfull_boxes = items // box_size\nleftover = items % box_size\nprint(full_boxes, leftover)'),
      L('input-conversion','Reading input and converting types','`input()` reads a line of text and returns a string. If you want arithmetic, convert the string into a number with `int()` or `float()`. The academy runner collects input lines before execution; each call consumes the next line from the playground input box.', 'name = input("What is your name? ")\nage = int(input("How old are you? "))\nprint(f"Hello, {name}! Next year you will be {age + 1}.")', 'What is your name? How old are you? Hello, Alex! Next year you will be 16.', 'Even if a learner types `15`, `input()` first returns the text `"15"`. `int()` converts that text into an integer. If the text is not a valid integer, Python raises `ValueError`, which should be handled when input may be unpredictable.', 'Read a city name and a number of days. Print a sentence using both values.', 'city = input("City: ")\ndays = int(input("Days: "))\n# print a sentence', 'Provide two input lines: a city, then a whole number.', 'Remember that `input()` returns text.', 'Convert the second value using `int()` before doing calculations.', 'city = input("City: ")\ndays = int(input("Days: "))\nprint(f"You selected {city} for {days} days.")')
    ]},
    {id:'strings-operators',number:2,title:'Strings and Operators',subtitle:'Work confidently with text, comparisons, and truth values.',level:'Beginner',icon:'Aa',topics:['String creation','Indexing and negative indexing','Slicing','String immutability','Concatenation and repetition','Escape sequences','strip(), split(), replace(), lower(), upper()','f-strings and numeric formatting','Comparison and assignment operators','Boolean logic','Identity and membership','Truthiness','Common type errors'],lessons:[
      L('string-tools','String methods and cleanup','A string is an immutable sequence of characters. Methods such as `.strip()`, `.lower()`, `.replace()`, and `.split()` return new values; they do not mutate the original string in place.', 'raw_text = "  PyTrail, Python, PYTHON  "\nclean = raw_text.strip()\nprint(clean.lower())\nprint(clean.replace("Python", "coding"))\nprint(clean.split(","))', 'pytrail, python, python\nPyTrail, coding, PYTHON\n[\'PyTrail\', \' Python\', \' PYTHON\']', 'Notice that `.replace()` is case-sensitive and only replaces matching text. Calling `.strip()` first changes which spaces remain. Method calls can be chained, but intermediate variables can make complex transformations easier to understand.', 'Clean the text `"  HELLO PYTHON  "` by removing surrounding whitespace and converting it to lowercase.', 'text = "  HELLO PYTHON  "\nclean = ...\nprint(clean)', 'The result should be `hello python`.', 'Use `.strip()` to remove surrounding whitespace.', 'Call `.lower()` on the cleaned result.', 'text = "  HELLO PYTHON  "\nclean = text.strip().lower()\nprint(clean)'),
      L('indexing-slicing','Indexing and slicing text','Python indexes sequences from zero. Negative indexes count backward from the end. A slice `text[start:stop]` includes the start index and excludes the stop index, which makes adjacent slices easy to join.', 'word = "PYTHON"\nprint(word[0])\nprint(word[-1])\nprint(word[1:4])\nprint(word[:2])\nprint(word[::2])', 'P\nN\nYTH\nPY\nPTO', 'The final slice `word[::2]` takes every second character. Asking for an index that is outside the string raises `IndexError`, while many slices safely return an empty string when bounds are beyond the sequence.', 'From `"programming"`, print the first three characters and the last four characters.', 'word = "programming"\nprint(...)\nprint(...)', 'Use one slice for the prefix and one negative slice for the suffix.', 'The first three characters occupy indexes 0 through 2.', 'A stop index is excluded; use `word[-4:]` for the last four.', 'word = "programming"\nprint(word[:3])\nprint(word[-4:])'),
      L('boolean-membership','Boolean logic and membership','Comparison operators produce booleans. `and` requires both conditions to be true, `or` needs at least one, and `not` reverses a truth value. Membership with `in` tests whether an item occurs in a collection or substring.', 'username = "mina_dev"\nprint("_" in username)\nprint(len(username) >= 3 and len(username) <= 20)\nprint(not username.startswith("admin"))', 'True\nTrue\nTrue', 'Keep conditions readable. Parentheses are useful when mixing `and` and `or`. Do not confuse `=` assignment with `==` equality comparison. `is` checks object identity and is not a replacement for `==` when comparing ordinary values.', 'Check whether `email` contains an `@` and has at least 5 characters.', 'email = "student@example.com"\nvalid = ...\nprint(valid)', 'Use `in` for the `@` test and `len()` for the length test.', 'Combine both comparisons with `and`.', 'Keep the conditions inside parentheses for readability.', 'email = "student@example.com"\nvalid = ("@" in email) and (len(email) >= 5)\nprint(valid)')
    ]},
    {id:'conditions',number:3,title:'Conditions and Decisions',subtitle:'Teach your program to choose what happens next.',level:'Beginner',icon:'⑂',topics:['if, elif, else','Nested conditions','Compound conditions','Comparison chains','Conditional expressions','Guard clauses','Boundary conditions','Logical mistakes'],lessons:[
      L('if-elif-else','Make decisions with if, elif, and else','Conditionals let a program choose a branch based on a true-or-false expression. Python uses a colon after each condition and indentation to mark the statements belonging to that branch.', 'temperature = 18\nif temperature >= 30:\n    print("Hot day")\nelif temperature >= 20:\n    print("Warm day")\nelse:\n    print("Bring a light layer")', 'Bring a light layer', 'Python checks the conditions from top to bottom and runs the first matching branch. The `else` branch is optional and runs when no preceding condition matched. Use four spaces for each indentation level as a common convention.', 'Write a program that prints `Adult` for age 18 or higher and `Under 18` otherwise.', 'age = 16\nif ...:\n    print(...)\nelse:\n    print(...)', 'Test both 16 and 18 to understand the boundary.', 'The condition uses `>= 18`.', 'Put the `print()` calls on indented lines below each branch.', 'age = 16\nif age >= 18:\n    print("Adult")\nelse:\n    print("Under 18")'),
      L('compound-conditions','Combine rules clearly','Real programs often have multiple requirements. Combine booleans with `and`, `or`, and `not`, and group them with parentheses so both Python and other readers can understand your intention.', 'score = 86\nsubmitted = True\nif score >= 80 and submitted:\n    print("Meets the target")\nelse:\n    print("Keep practicing")', 'Meets the target', '`and` binds more tightly than `or`; parentheses reduce mistakes when both appear. Test boundary values, such as 79, 80, and 81, rather than checking only a typical case.', 'A free shipping rule applies when the cart total is at least 50 OR the customer has a membership. Print `Free shipping` when the rule applies.', 'total = 35\nmember = False\n# write the condition', 'Try both `member = False` and `member = True`.', 'Use `or` because either condition is enough.', 'The rule is `total >= 50 or member`.', 'total = 35\nmember = False\nif total >= 50 or member:\n    print("Free shipping")\nelse:\n    print("Shipping applies")'),
      L('guard-clauses','Use guard clauses and check boundaries','A guard clause handles a condition that should end or redirect a function early. Boundary testing means checking values at, just below, and just above a threshold; many logic bugs happen at these edges.', 'def describe_score(score):\n    if score < 0 or score > 100:\n        return "Invalid score"\n    if score >= 50:\n        return "Pass"\n    return "Try again"\n\nprint(describe_score(50))\nprint(describe_score(120))', 'Pass\nInvalid score', 'Early returns prevent the rest of the function from running when an invalid value is detected. Once the value is known to be within range, later checks become simpler.', 'Write `classify_age(age)` that returns `Invalid` if age is negative, `Child` below 13, and `Teen or adult` otherwise.', 'def classify_age(age):\n    # add checks\n    pass\n\nprint(classify_age(12))', 'The returned text should depend on the order of the conditions.', 'Check invalid values first, then the lower age boundary.', 'Use `return` to send a string back from the function.', 'def classify_age(age):\n    if age < 0:\n        return "Invalid"\n    if age < 13:\n        return "Child"\n    return "Teen or adult"\n\nprint(classify_age(12))')
    ]},
    {id:'loops',number:4,title:'Loops',subtitle:'Repeat work safely and efficiently.',level:'Beginner',icon:'↻',topics:['for and while','range()','Iterating over strings and collections','Counting and accumulators','Nested loops','break, continue, pass','Loop else','Infinite loops','Off-by-one errors'],lessons:[
      L('for-range','Repeat a task with for and range','A `for` loop visits items in an iterable. `range(stop)` generates integers from zero up to, but not including, `stop`. The three-argument form `range(start, stop, step)` lets you control the starting point and increment.', 'for number in range(1, 6):\n    print(number)\n\nfor even in range(2, 9, 2):\n    print(even, end=" ")', '1\n2\n3\n4\n5\n2 4 6 8 ', 'The first range includes 1 through 5 because the stop value 6 is excluded. `end=" "` tells `print()` to use a space rather than a newline at the end.', 'Print every multiple of 3 from 3 through 18.', 'for number in range(...):\n    print(number)', 'Use a step of 3 and choose a stop value that includes 18.', 'Start at 3.', 'The stop value must be greater than 18; 19 is sufficient for this step.', 'for number in range(3, 19, 3):\n    print(number)'),
      L('while-accumulator','Use while loops and accumulators','A `while` loop repeats while its condition remains true. An accumulator stores a running result, such as a total. Change the loop condition or related state on each iteration so the loop can eventually finish.', 'total = 0\nnumber = 1\nwhile number <= 4:\n    total += number\n    number += 1\nprint(total)', '10', '`total += number` is shorthand for `total = total + number`. The variable `number` moves toward the stopping condition. If it never changes in a way that makes the condition false, the loop can run forever.', 'Use a loop to add the numbers from 1 through 10 and print the total.', 'total = 0\nnumber = 1\nwhile number <= 10:\n    # update total\n    # advance number\n    pass\nprint(total)', 'The total should be 55.', 'Add the current number to the total during every iteration.', 'Increase `number` by one.', 'total = 0\nnumber = 1\nwhile number <= 10:\n    total += number\n    number += 1\nprint(total)'),
      L('break-continue','Control a loop with break and continue','`break` exits the nearest loop immediately. `continue` skips the remainder of the current iteration and begins the next one. Use these controls when they make the algorithm clearer, not as a replacement for understandable conditions.', 'for number in range(1, 8):\n    if number == 3:\n        continue\n    if number == 6:\n        break\n    print(number)', '1\n2\n4\n5', 'The value 3 is skipped, while the loop stops entirely when it reaches 6. `pass` is different: it does nothing and can serve as a temporary placeholder while writing code.', 'Print numbers 1 to 10 except 4 and 7, then stop after 9.', 'for number in range(1, 11):\n    # decide whether to skip or stop\n    print(number)', 'Your output must not include 4, 7, or any value after 9.', 'Use `continue` for the two values to skip.', 'Use `break` when the number reaches 10.', 'for number in range(1, 11):\n    if number in (4, 7):\n        continue\n    if number == 10:\n        break\n    print(number)')
    ]},
    {id:'data-structures',number:5,title:'Data Structures',subtitle:'Store, organize, and transform groups of values.',level:'Beginner → Intermediate',icon:'▦',topics:['List creation, indexing, slicing, mutation, nesting, methods, copying, references, comprehensions','Tuple creation, packing, unpacking, immutability, use cases','Sets, uniqueness, membership, union, intersection, difference, symmetric difference','Dictionaries, keys, values, updates, deletion, iteration, get(), items(), nesting, comprehensions','Aliasing, mutability, equality versus identity, collection choice'],lessons:[
      L('lists-tuples','Lists, tuples, and mutation','Lists are ordered and mutable, so you can change them after creation. Tuples are ordered but immutable. Choose the collection that matches the job: lists for editable sequences and tuples for fixed groups of related values.', 'scores = [72, 88, 91]\nscores.append(95)\nscores[0] = 75\nprint(scores)\npoint = (4, 9)\nx, y = point\nprint(x, y)', '[75, 88, 91, 95]\n4 9', '`append()` adds one item to the end. Index assignment changes a list item. Tuple unpacking assigns each tuple member to a matching variable in one statement.', 'Start with `[5, 10, 15]`, append 20, and print the last value.', 'values = [5, 10, 15]\n# append 20\nprint(values[-1])', 'The last value should be 20.', 'Use `.append(20)`.', 'Negative index `-1` means the final item.', 'values = [5, 10, 15]\nvalues.append(20)\nprint(values[-1])'),
      L('sets-dictionaries','Sets and dictionaries','A set stores unique values and is useful for membership and set operations. A dictionary maps unique keys to values. Dictionaries preserve insertion order in modern Python, but you should choose them primarily because key-based lookup describes your data clearly.', 'tags = {"python", "coding", "python"}\nprint(len(tags))\nprofile = {"name": "Mina", "level": 2}\nprofile["level"] = 3\nprofile["active"] = True\nprint(profile.get("name"))\nprint(profile["level"])', '2\nMina\n3', 'The duplicate string only appears once in the set. `dict.get(key)` can return `None` or a supplied default if a key is missing; direct indexing raises `KeyError` for an absent key.', 'Count how many times each word appears in `words = ["red", "blue", "red"]` using a dictionary.', 'words = ["red", "blue", "red"]\ncounts = {}\n# count each word\nprint(counts)', 'The final dictionary should count red as 2 and blue as 1.', 'Loop over the words and read the current count with a default of zero.', 'Store the old count plus one back under the word key.', 'words = ["red", "blue", "red"]\ncounts = {}\nfor word in words:\n    counts[word] = counts.get(word, 0) + 1\nprint(counts)'),
      L('comprehensions-copying','Comprehensions, copies, and references','A comprehension builds a collection from an iterable in a compact expression. A shallow list copy creates a new outer list but does not recursively copy nested mutable objects. Assignment alone makes another name refer to the same object.', 'numbers = [1, 2, 3, 4, 5]\nsquares = [n * n for n in numbers if n % 2 == 1]\noriginal = [[1], [2]]\nshallow = original.copy()\nshallow[0].append(9)\nprint(squares)\nprint(original)', '[1, 9, 25]\n[[1, 9], [2]]', 'The filter `if n % 2 == 1` keeps odd values. The nested inner list is shared between `original` and `shallow`. Use `copy.deepcopy()` when independent nested mutable structures are truly needed.', 'Create a list containing the uppercase version of each non-empty name.', 'names = ["mina", "", "alex"]\nupper_names = [...]\nprint(upper_names)', 'The result should include MINA and ALEX, but not an empty value.', 'A list comprehension can transform each `name`.', 'Add a filter such as `if name` to ignore empty strings.', 'names = ["mina", "", "alex"]\nupper_names = [name.upper() for name in names if name]\nprint(upper_names)')
    ]},
    {id:'functions',number:6,title:'Functions',subtitle:'Turn ideas into reusable, testable building blocks.',level:'Intermediate',icon:'ƒ',topics:['Defining and calling functions','Parameters and arguments','Return versus print','Positional and keyword arguments','Defaults, keyword-only and positional-only parameters','*args and **kwargs','Scope and LEGB','Docstrings and type hints','Pure functions','Decomposition','Mutable default argument pitfalls'],lessons:[
      L('define-return','Define functions and return values','A function groups work behind a meaningful name. Parameters are names in the definition; arguments are values supplied by a caller. `return` sends a result back to the caller, while `print()` only displays a value.', 'def rectangle_area(width, height):\n    """Return the area of a rectangle."""\n    return width * height\n\narea = rectangle_area(6, 4)\nprint(area)', '24', 'The function body is indented. The docstring documents the purpose. The `return` statement ends the function call and passes the calculated area back into `area`.', 'Write `greet(name)` that returns `"Hello, NAME!"` with the provided name.', 'def greet(name):\n    # return a greeting\n    pass\n\nprint(greet("Sam"))', 'Printing the returned string should show Hello, Sam!', 'Build a string with an f-string.', 'Return that string rather than printing inside the function.', 'def greet(name):\n    return f"Hello, {name}!"\n\nprint(greet("Sam"))'),
      L('scope-defaults','Scope, defaults, and safe arguments','Names created inside a function usually belong to that local scope. Python resolves names using the LEGB rule: Local, Enclosing, Global, Built-in. Avoid mutating a shared global variable when a return value or explicit parameter would be clearer.', 'def make_label(text, prefix="Note"):\n    return f"{prefix}: {text}"\n\nprint(make_label("Practice"))\nprint(make_label("Review", prefix="Task"))', 'Note: Practice\nTask: Review', 'Default values are evaluated when the function is defined, not each time it is called. For mutable defaults such as lists, use `None` and create a fresh list inside the function to avoid accidental sharing.', 'Create `add_item(item, items=None)` that returns a list containing the item and any previous list values.', 'def add_item(item, items=None):\n    # handle None and return a list\n    pass\n\nprint(add_item("pen"))', 'Calling it without an existing list should not cause an error.', 'Start with an empty list only when `items is None`.', 'Copy the incoming list first if you do not want to mutate the caller’s list.', 'def add_item(item, items=None):\n    if items is None:\n        items = []\n    result = items.copy()\n    result.append(item)\n    return result\n\nprint(add_item("pen"))'),
      L('args-keyword-types','Flexible parameters and type hints','`*args` gathers extra positional arguments into a tuple, while `**kwargs` gathers extra keyword arguments into a dictionary. Type annotations communicate expectations to readers and tools, but Python does not automatically enforce them at runtime.', 'def total(*numbers: int) -> int:\n    return sum(numbers)\n\ndef describe(**details: str) -> None:\n    for key, value in details.items():\n        print(f"{key}: {value}")\n\nprint(total(2, 3, 5))\ndescribe(language="Python", level="beginner")', '10\nlanguage: Python\nlevel: beginner', 'Use flexible parameters when a function genuinely benefits from variable argument counts. Do not use them everywhere: explicit parameters are often easier for beginners and future maintainers.', 'Write a function `maximum_of(*numbers)` that returns the largest value, then test it with 3, 9, and 4.', 'def maximum_of(*numbers):\n    # return the maximum\n    pass\n\nprint(maximum_of(3, 9, 4))', 'The result should be 9.', 'Python has a built-in `max()` function.', 'The `numbers` parameter is a tuple, even if there is only one argument.', 'def maximum_of(*numbers):\n    return max(numbers)\n\nprint(maximum_of(3, 9, 4))')
    ]},
    {id:'debugging',number:7,title:'Debugging and Exceptions',subtitle:'Understand failures and turn them into useful feedback.',level:'Intermediate',icon:'⌕',topics:['Syntax, runtime, and logical errors','Tracebacks and debugging workflow','try/except/else/finally','Raising and choosing exceptions','Custom exception classes','Input validation','Defensive programming'],lessons:[
      L('read-tracebacks','Read errors and tracebacks','Errors are part of programming. A syntax error means Python could not parse the code. A runtime exception happens while the program runs. A logical error means the code runs but produces the wrong result. Tracebacks show where the exception travelled through the program.', 'numbers = [10, 20, 30]\ntry:\n    print(numbers[5])\nexcept IndexError as error:\n    print(f"The index is out of range: {error}")', 'The index is out of range: list index out of range', 'Catch the specific exception you can reasonably handle. Broadly catching every exception can hide programming bugs and make problems harder to discover.', 'Ask Python to convert `"twelve"` into an integer and display a friendly message if conversion fails.', 'text = "twelve"\ntry:\n    number = int(text)\nexcept ValueError:\n    # show a useful message\n    pass', 'The program should continue and display a helpful message instead of crashing.', 'The conversion raises `ValueError` for non-numeric text.', 'Catch `ValueError` specifically.', 'text = "twelve"\ntry:\n    number = int(text)\nexcept ValueError:\n    print("Please enter a whole number.")'),
      L('try-except-finally','Handle exceptions without hiding bugs','Use `try` for operations that may fail, `except` for expected failures, `else` for the success path, and `finally` for cleanup that should happen either way. Exception handling should make behavior safer and more understandable.', 'text = "24"\ntry:\n    value = int(text)\nexcept ValueError:\n    print("That was not a whole number.")\nelse:\n    print(value * 2)\nfinally:\n    print("Input processing finished.")', '48\nInput processing finished.', 'The `else` block does not run when an exception is raised in the `try` block. The `finally` block runs whether conversion worked or not, making it suitable for predictable cleanup tasks.', 'Adapt the example so the text `"oops"` is handled safely and the final message always prints.', 'text = "oops"\ntry:\n    value = int(text)\n    print(value)\nexcept ValueError:\n    print("Invalid number")\nfinally:\n    print("Finished")', 'Try changing `text` to `"6"` to compare both paths.', 'Leave the `finally` block outside the `except` block.', 'Catch the exception type that `int()` raises for invalid text.', 'text = "oops"\ntry:\n    value = int(text)\n    print(value)\nexcept ValueError:\n    print("Invalid number")\nfinally:\n    print("Finished")'),
      L('raise-custom-errors','Raise exceptions and validate inputs','Raise an exception when a function receives a value that violates its contract. Standard exceptions such as `ValueError` and `TypeError` communicate familiar problems. Custom exception classes help libraries describe domain-specific failures.', 'def set_percentage(value):\n    if not 0 <= value <= 100:\n        raise ValueError("percentage must be from 0 to 100")\n    return value\n\ntry:\n    print(set_percentage(120))\nexcept ValueError as error:\n    print(error)', 'percentage must be from 0 to 100', 'The `raise` statement interrupts the normal path and sends the exception to a matching handler. Validate at boundaries, then keep the rest of the function focused on its main task.', 'Create a function `positive_square(n)` that raises `ValueError` for values below zero and returns `n * n` otherwise.', 'def positive_square(n):\n    # validate, then return square\n    pass\n\nprint(positive_square(4))', 'Four should produce 16; a negative input should raise ValueError.', 'Check `n < 0` before doing the calculation.', 'Use `raise ValueError("...")` for invalid numeric input.', 'def positive_square(n):\n    if n < 0:\n        raise ValueError("n must not be negative")\n    return n * n\n\nprint(positive_square(4))')
    ]},
    {id:'files-data',number:8,title:'Files and Data',subtitle:'Read, write, and structure information.',level:'Intermediate',icon:'▤',topics:['open() and file modes','Reading, writing, appending','with blocks','Relative and absolute paths','pathlib','Encoding and file errors','JSON and CSV','Serialization fundamentals','Browser virtual filesystem limits'],browserNote:'Pyodide has a virtual filesystem inside the browser. File examples can work there, but browser files do not automatically become files on your Windows computer. Download or upload functionality needs explicit browser APIs.',lessons:[
      L('file-basics','Read and write files safely','For ordinary local Python, `open()` works with files on the computer. Use a `with` block so the file is closed even if an error occurs. Browser Pyodide uses a virtual filesystem, so files created there are not automatically saved to your real computer.', 'from pathlib import Path\n\npath = Path("notes.txt")\npath.write_text("Practice Python\\nKeep experimenting!", encoding="utf-8")\ncontent = path.read_text(encoding="utf-8")\nprint(content)', 'Practice Python\nKeep experimenting!', '`Path.write_text()` and `Path.read_text()` are convenient for small text files. Use an explicit encoding such as UTF-8 for predictable text handling. In this browser environment the example writes into the runtime’s virtual filesystem.', 'Write `"Hello file"` to `hello.txt`, then read and print it.', 'from pathlib import Path\npath = Path("hello.txt")\n# write and read the file', 'The printed text should be Hello file.', 'Create the file path with `Path("hello.txt")`.', 'Call `write_text()` before `read_text()`.', 'from pathlib import Path\npath = Path("hello.txt")\npath.write_text("Hello file", encoding="utf-8")\nprint(path.read_text(encoding="utf-8"))'),
      L('json-csv','Store structured data with JSON and CSV','JSON is a portable text format for nested dictionaries, lists, strings, numbers, booleans, and null values. CSV is useful for tabular rows. The `json` and `csv` modules provide standard-library support without requiring a web API.', 'import json\n\nstudent = {"name": "Mina", "scores": [88, 94]}\nencoded = json.dumps(student)\nrestored = json.loads(encoded)\nprint(restored["name"])\nprint(sum(restored["scores"]))', 'Mina\n182', '`json.dumps()` turns a Python object into JSON text; `json.loads()` parses JSON text back into Python values. File versions use `dump()` and `load()` with open file objects.', 'Create a dictionary for a book with title and pages, convert it to JSON text, and read the title back.', 'import json\nbook = {"title": "...", "pages": 120}\ntext = ...\nrestored = ...\nprint(restored["title"])', 'Keep strings and numbers as the appropriate Python types.', 'Use `json.dumps(book)` and `json.loads(text)`.', 'The restored object is a dictionary, so access it with the `title` key.', 'import json\nbook = {"title": "Python Basics", "pages": 120}\ntext = json.dumps(book)\nrestored = json.loads(text)\nprint(restored["title"])'),
      L('paths-file-errors','Paths, encodings, and file errors','Use `pathlib.Path` to build paths in a way that works across operating systems. File operations can fail because a file is missing, permissions are limited, or an encoding is wrong. Handle expected failures and give the user a clear next step.', 'from pathlib import Path\n\npath = Path("missing_notes.txt")\ntry:\n    print(path.read_text(encoding="utf-8"))\nexcept FileNotFoundError:\n    print("No notes file exists yet.")', 'No notes file exists yet.', 'Catching `FileNotFoundError` handles only the missing-file situation; other exceptions may still deserve attention. Avoid silently ignoring every `OSError` because it can conceal useful information.', 'Check whether `draft.txt` exists before reading it.', 'from pathlib import Path\npath = Path("draft.txt")\nif ...:\n    print(path.read_text(encoding="utf-8"))\nelse:\n    print("Not found")', 'Use `Path.exists()` to check the path.', 'The check returns a boolean.', 'from pathlib import Path\npath = Path("draft.txt")\nif path.exists():\n    print(path.read_text(encoding="utf-8"))\nelse:\n    print("Not found")')
    ]},
    {id:'modules-env',number:9,title:'Modules, Packages, and Environments',subtitle:'Reuse code and manage projects reproducibly.',level:'Intermediate',icon:'⬡',topics:['import and from import','Aliases and standard-library modules','Creating modules and packages','__name__ == "__main__"','Python versions','pip and virtual environments','requirements.txt','Reproducible environments','Import errors'],browserNote:'Browser Python cannot install every package or emulate a local virtual environment and operating system. Use these examples to learn import syntax; follow the local setup guide for real project environments.',lessons:[
      L('imports-main','Import modules and protect script entry points','A module is a Python file. Import statements let you reuse functions and data from other modules. The `if __name__ == "__main__":` pattern runs setup code only when a file is executed as the main program, not when imported.', 'import math\nfrom statistics import mean as average\n\nprint(math.sqrt(81))\nprint(average([2, 4, 6]))\n\ndef main():\n    print("Program entry point")\n\nmain()', '9.0\n4\nProgram entry point', 'The alias `average` gives the imported function a name that fits the example. Keep imports near the top of the file and avoid naming your own files `math.py` or `statistics.py`, which may shadow standard-library modules.', 'Import `random` and print a random integer from 1 through 6.', 'import random\n# print a random integer', 'The output is one integer from 1 to 6 inclusive.', 'Use `random.randint(a, b)`.', 'Both endpoints are included for `randint()`.', 'import random\nprint(random.randint(1, 6))'),
      L('venvs-pip','Understand pip and virtual environments','A virtual environment isolates a project’s installed dependencies from other projects. `pip` installs packages into the selected Python environment. Pinning dependencies in a requirements file helps another developer recreate a similar environment.', 'from pathlib import Path\n\nrequirements = ["requests==2.32.3", "pytest>=8.0"]\nprint("\\n".join(requirements))\nprint("Save dependencies in requirements.txt for a local project.")', 'requests==2.32.3\npytest>=8.0\nSave dependencies in requirements.txt for a local project.', 'This sample explains the file content without installing packages. On a local machine, create a virtual environment using `python -m venv .venv`, activate it, then install the dependencies. Activation commands differ by shell and operating system.', 'Write a requirements list to `requirements.txt` in the virtual filesystem.', 'from pathlib import Path\nitems = ["requests==2.32.3"]\n# write the lines to a file', 'Use `write_text()` and join the lines with a newline.', 'The file should have one requirement per line.', 'Pass `"\\n".join(items)` to `write_text()`.', 'from pathlib import Path\nitems = ["requests==2.32.3"]\nPath("requirements.txt").write_text("\\n".join(items), encoding="utf-8")\nprint(Path("requirements.txt").read_text(encoding="utf-8"))'),
      L('package-design','Organize reusable project code','As programs grow, separate related functionality into modules with clear names. Packages group modules together. Import cycles, ambiguous filenames, and unexpected global side effects are common sources of confusing import errors.', 'def format_user(name):\n    """Return a display label for a learner."""\n    cleaned = name.strip()\n    return f"Learner: {cleaned}"\n\nprint(format_user("  Alex  "))', 'Learner: Alex', 'Although this small example stays in one file, you could put `format_user` in `text_tools.py` and import it elsewhere. Keep a module’s top-level code focused on definitions rather than doing work immediately when it is imported.', 'Create a function in your current file that formats a product name and reuse it twice.', 'def product_label(name):\n    # return a neat label\n    pass\n\nprint(product_label("Keyboard"))', 'The function should clean surrounding spaces.', 'Use `.strip()`.', 'Return a string; then call the same function with a second input.', 'def product_label(name):\n    return f"Product: {name.strip()}"\n\nprint(product_label("Keyboard"))')
    ]},
    {id:'oop',number:10,title:'Object-Oriented Programming',subtitle:'Model related state and behavior with classes.',level:'Intermediate',icon:'▣',topics:['Objects and classes','Attributes and methods','self and __init__','Instance versus class attributes','Encapsulation','Inheritance and composition','Polymorphism and overriding','super()','Properties, class methods, static methods','Dunder methods','Dataclasses','Abstract base classes','When not to use a class'],lessons:[
      L('classes-init','Create classes, objects, and methods','A class describes a kind of object. An instance stores its own state in attributes. The first parameter of an ordinary instance method is conventionally named `self` and refers to the object receiving the method call.', 'class Counter:\n    def __init__(self, start=0):\n        self.value = start\n\n    def increment(self):\n        self.value += 1\n        return self.value\n\nfirst = Counter(4)\nprint(first.increment())\nprint(first.value)', '5\n5', '`__init__` initializes an instance after it has been created. Two instances of `Counter` have separate `value` attributes. Avoid mutable class attributes when each instance should get its own list or dictionary.', 'Create a `Dog` class that stores a name and has a `speak()` method returning `"Woof! I am NAME"`.', 'class Dog:\n    def __init__(self, name):\n        self.name = name\n    def speak(self):\n        # return a greeting\n        pass\n\nprint(Dog("Pip").speak())', 'The method should use the object’s `name` attribute.', 'Use an f-string with `self.name`.', 'Return the string; do not rely on printing inside the method.', 'class Dog:\n    def __init__(self, name):\n        self.name = name\n    def speak(self):\n        return f"Woof! I am {self.name}"\n\nprint(Dog("Pip").speak())'),
      L('inheritance-composition','Use inheritance and composition deliberately','Inheritance models an “is a” relationship and lets a subclass specialize a base class. Composition models a “has a” relationship by storing another object. Prefer the simplest model that expresses the domain clearly.', 'class Battery:\n    def __init__(self, percent):\n        self.percent = percent\n\nclass Phone:\n    def __init__(self, battery):\n        self.battery = battery\n\nphone = Phone(Battery(80))\nprint(phone.battery.percent)', '80', '`Phone` has a `Battery`, so composition fits. Inheritance is useful when a subtype really can be used wherever its parent type is expected. Use `super()` when a subclass needs to extend parent initialization.', 'Create a `SavingsAccount` class with a `balance` and a `deposit(amount)` method.', 'class SavingsAccount:\n    def __init__(self, balance=0):\n        self.balance = balance\n    def deposit(self, amount):\n        # add a deposit\n        pass', 'A deposit of 25 should increase a starting balance of 100 to 125.', 'Update `self.balance`.', 'Return the new balance to make the method easy to test.', 'class SavingsAccount:\n    def __init__(self, balance=0):\n        self.balance = balance\n    def deposit(self, amount):\n        self.balance += amount\n        return self.balance\n\nprint(SavingsAccount(100).deposit(25))'),
      L('dataclasses-properties','Dataclasses, properties, and useful representations','Dataclasses reduce boilerplate for classes primarily used to store data. A property can expose a computed or validated attribute through attribute syntax. Dunder methods such as `__repr__` let objects integrate with common Python operations.', 'from dataclasses import dataclass\n\n@dataclass\nclass Book:\n    title: str\n    pages: int\n\nbook = Book("Python in Practice", 240)\nprint(book.title)\nprint(book.pages)', 'Python in Practice\n240', 'The `@dataclass` decorator generates helpful methods such as an initializer and readable representation for straightforward data classes. For complicated invariants or behavior, write explicit methods and tests.', 'Create a `Point` dataclass with `x` and `y`, then print the distance squared from the origin.', 'from dataclasses import dataclass\n\n@dataclass\nclass Point:\n    x: int\n    y: int\n\npoint = Point(3, 4)\n# calculate distance squared', 'For (3, 4), x squared plus y squared is 25.', 'Use `point.x ** 2 + point.y ** 2`.', 'Distance squared avoids needing `math.sqrt()`.', 'from dataclasses import dataclass\n\n@dataclass\nclass Point:\n    x: int\n    y: int\n\npoint = Point(3, 4)\nprint(point.x ** 2 + point.y ** 2)')
    ]},
    {id:'iterators',number:11,title:'Iterators and Generators',subtitle:'Process data lazily and build efficient iteration tools.',level:'Advanced',icon:'⇢',topics:['Iterable versus iterator','iter() and next()','Iterator protocol','Generator functions and yield','Generator expressions','Lazy evaluation and memory','List/set/dictionary comprehensions','Readability trade-offs'],lessons:[
      L('iterable-iterator','Understand iterables and iterators','An iterable can produce an iterator; an iterator yields one item at a time and remembers its current position. `iter()` requests an iterator and `next()` requests the next value. A finished iterator raises `StopIteration`.', 'colors = ["violet", "blue"]\niterator = iter(colors)\nprint(next(iterator))\nprint(next(iterator))', 'violet\nblue', 'A list can be iterated over more than once by requesting a new iterator. An iterator itself is generally consumed as values are requested, which is useful for streams and lazily generated data.', 'Create an iterator from `range(3)` and print its first value.', 'values = iter(range(3))\nprint(...)', 'The first value is 0.', 'Pass the iterator to `next()`.', 'Each `next()` call advances the iterator.', 'values = iter(range(3))\nprint(next(values))'),
      L('generator-yield','Write generator functions with yield','A generator function uses `yield` to produce values over time. Calling it returns a generator object; the function body proceeds as the consumer requests each value. This can avoid building a large list in memory.', 'def countdown(start):\n    while start > 0:\n        yield start\n        start -= 1\n\nprint(list(countdown(3)))', '[3, 2, 1]', 'Unlike `return`, `yield` suspends the generator and preserves its local state for the next request. Generators work well for sequences, file processing, and pipelines where all results do not need to exist at once.', 'Write a generator `evens(limit)` that yields even numbers below limit.', 'def evens(limit):\n    number = 0\n    while number < limit:\n        # yield evens\n        number += 1\n\nprint(list(evens(7)))', 'The output should be [0, 2, 4, 6].', 'Check whether the current number is even.', 'Use `yield number` inside that condition.', 'def evens(limit):\n    number = 0\n    while number < limit:\n        if number % 2 == 0:\n            yield number\n        number += 1\n\nprint(list(evens(7)))'),
      L('comprehension-tradeoffs','Choose between comprehensions and loops','Comprehensions are concise ways to create a collection from an iterable. They are best when the transformation and optional filter are easy to read. If an expression becomes difficult to scan, a normal loop is often clearer.', 'prices = [12, 7, 25, 4]\nexpensive = {price: price * 1.1 for price in prices if price >= 10}\nprint(expensive)', '{12: 13.200000000000001, 25: 27.500000000000004}', 'Floating-point values cannot represent many decimal fractions exactly. For currency calculations, use `decimal.Decimal` with deliberate decimal input instead of assuming binary floats are exact.', 'Build a list of the lengths of non-empty words.', 'words = ["cat", "", "python"]\nlengths = [...]\nprint(lengths)', 'The result should be [3, 6].', 'Use `len(word)` as the expression.', 'Use `if word` to filter out empty strings.', 'words = ["cat", "", "python"]\nlengths = [len(word) for word in words if word]\nprint(lengths)')
    ]},
    {id:'advanced-features',number:12,title:'Advanced Python Features',subtitle:'Explore expressive patterns and the data model.',level:'Advanced',icon:'✧',topics:['First-class functions and closures','Decorators and decorator arguments','functools.wraps','Context managers','Advanced unpacking','Structural pattern matching','Type annotations and unions','Optional values and None','Protocols and structural typing','Enums and named tuples','Dataclasses','Descriptors','Metaclasses (optional advanced topic)','Advanced class design'],lessons:[
      L('closures-decorators','Understand closures and decorators','Functions are first-class values: they can be passed to other functions and returned from functions. A closure remembers variables from its enclosing scope. A decorator wraps a function to add behavior without changing its call sites.', 'def announce(function):\n    def wrapper(*args, **kwargs):\n        print("Starting")\n        result = function(*args, **kwargs)\n        print("Finished")\n        return result\n    return wrapper\n\n@announce\ndef greet(name):\n    print(f"Hello, {name}!")\n\ngreet("Mina")', 'Starting\nHello, Mina!\nFinished', 'The `@announce` syntax assigns the decorated function to the wrapper returned by `announce`. Production decorators commonly use `functools.wraps(function)` so metadata such as a function’s name and docstring is preserved.', 'Write a decorator that prints `Calling function` before the wrapped function runs.', 'def log_call(function):\n    def wrapper(*args, **kwargs):\n        # print a message and call function\n        pass\n    return wrapper', 'The wrapper should pass both positional and keyword arguments through.', 'Use `function(*args, **kwargs)`.', 'Return the wrapped call result so callers can still use it.', 'def log_call(function):\n    def wrapper(*args, **kwargs):\n        print("Calling function")\n        return function(*args, **kwargs)\n    return wrapper'),
      L('context-managers','Use context managers to manage resources','Context managers define setup and cleanup behavior around a block. The `with` statement is commonly used with files because it closes them reliably. Custom managers can be created with a class implementing `__enter__` and `__exit__`, or with `contextlib` tools.', 'from contextlib import contextmanager\n\n@contextmanager\ndef announce_task(name):\n    print(f"Begin: {name}")\n    try:\n        yield\n    finally:\n        print(f"End: {name}")\n\nwith announce_task("practice"):\n    print("Working")', 'Begin: practice\nWorking\nEnd: practice', 'The `finally` section runs even if the block raises an exception. This is a simple resource-management pattern: acquire, use, and release in a predictable order.', 'Use the provided context-manager pattern with the label `report`, and print `Building report` inside.', 'from contextlib import contextmanager\n\n@contextmanager\ndef task(name):\n    print("Start", name)\n    try:\n        yield\n    finally:\n        print("End", name)\n\nwith task("report"):\n    print("Building report")', 'Observe that the end message comes after the work.', 'The `yield` marks the body of the `with` block.', 'Code after `yield` in the `finally` runs on exit.', 'from contextlib import contextmanager\n\n@contextmanager\ndef task(name):\n    print("Start", name)\n    try:\n        yield\n    finally:\n        print("End", name)\n\nwith task("report"):\n    print("Building report")'),
      L('typing-pattern-match','Type annotations and structural pattern matching','Type hints document intent for both humans and static-analysis tools. Python does not automatically validate every hint. Structural pattern matching with `match`/`case` compares a value against patterns and is useful when several clear alternatives exist.', 'def describe(value: int | str) -> str:\n    match value:\n        case int():\n            return f"Number: {value}"\n        case str():\n            return f"Text: {value}"\n\nprint(describe(7))\nprint(describe("hi"))', 'Number: 7\nText: hi', 'The `int | str` annotation is a union type in modern Python. Pattern matching is available in Python 3.10 and later. For ordinary two-way choices an `if` statement can be simpler; use `match` when patterns improve clarity.', 'Write `describe_status()` that returns `Ready` for the string `ready`, `Stopped` for `stopped`, and `Unknown` otherwise.', 'def describe_status(status):\n    match status:\n        case "ready":\n            return "Ready"\n        # add the remaining cases', 'Include a wildcard `_` case for all other values.', 'Add `case "stopped":`.', 'Use `case _:` as the fallback.', 'def describe_status(status):\n    match status:\n        case "ready": return "Ready"\n        case "stopped": return "Stopped"\n        case _: return "Unknown"\n\nprint(describe_status("ready"))')
    ]},
    {id:'stdlib',number:13,title:'Python Standard Library',subtitle:'Use batteries-included modules for common jobs.',level:'Intermediate → Advanced',icon:'⌘',topics:['math, random, statistics','datetime and time','pathlib, os, sys','json and csv','re','collections','itertools, functools, operator','decimal and fractions','uuid and logging','argparse','unittest','sqlite3','subprocess, tempfile, shutil, zipfile','hashlib and secrets','enum and dataclasses'],browserNote:'Most standard-library examples here are suitable for Pyodide, but APIs tied to real processes, OS services, system paths, or native behavior may be restricted or behave differently in a browser.',lessons:[
      L('useful-stdlib','Choose the right standard-library tool','The standard library offers well-tested tools so you do not need to reinvent common functionality. Read module documentation for exact behavior, supported versions, and environment assumptions.', 'from collections import Counter\nfrom statistics import mean\n\nwords = ["python", "code", "python", "learn"]\nprint(Counter(words).most_common(1))\nprint(mean([10, 20, 30]))', "[('python', 2)]\n20", '`Counter` counts hashable items and is useful for frequency analysis. `statistics.mean()` calculates an arithmetic mean. Pick the module that already expresses the operation you need.', 'Use `Counter` to count letters in the word `banana`.', 'from collections import Counter\nprint(Counter("banana"))', 'The output should show counts for b, a, and n.', 'A string is iterable, so `Counter` can consume its characters.', 'The letter `a` appears three times.', 'from collections import Counter\nprint(Counter("banana"))'),
      L('datetime-random','Work with dates, numbers, and randomness','Use `datetime` for date and time values and `random` for simulations or casual randomized choices. Use `secrets` rather than `random` when creating security-sensitive tokens, because `random` is not designed for cryptography.', 'from datetime import date, timedelta\nimport random\n\nrandom.seed(0)  # Fixed seed makes this teaching example repeatable.\ntoday = date(2026, 1, 1)\nprint(today + timedelta(days=7))\nprint(random.choice(["red", "blue", "green"]))', '2026-01-08\nblue', 'The date is explicitly set, and a fixed random seed makes this example repeatable. In real simulations, remove the seed when you want a new sequence on each run.', 'Create a date for 2026-05-10 and print the date seven days later.', 'from datetime import date, timedelta\nstart = date(2026, 5, 10)\n# add seven days', 'The result should be 2026-05-17.', 'Use a `timedelta(days=7)`.', 'Add the timedelta to the date.', 'from datetime import date, timedelta\nstart = date(2026, 5, 10)\nprint(start + timedelta(days=7))'),
      L('logging-security','Logging, hashes, and secure random values','Use logging levels to record events that matter during troubleshooting. A cryptographic hash is a one-way digest, not encryption. For security tokens, use `secrets` rather than predictable pseudo-random values.', 'import hashlib\nimport secrets\n\nmessage = "learn Python"\ndigest = hashlib.sha256(message.encode("utf-8")).hexdigest()\nprint(len(digest))\nprint(len(secrets.token_hex(8)))', '64\n16', 'SHA-256 produces a 256-bit digest represented here as 64 hexadecimal characters. The secure token uses eight random bytes encoded as 16 hex characters. Never store plaintext passwords; use a suitable password-hashing scheme with salt for real authentication systems.', 'Calculate a SHA-256 digest for `"hello"` and print its first 12 characters.', 'import hashlib\nmessage = "hello"\n# hash encoded message and print prefix', 'Call `.encode("utf-8")` before hashing the bytes.', 'Use `hashlib.sha256(...).hexdigest()`.', 'import hashlib\nmessage = "hello"\ndigest = hashlib.sha256(message.encode("utf-8")).hexdigest()\nprint(digest[:12])')
    ]},
    {id:'algorithms',number:14,title:'Algorithms and Computational Thinking',subtitle:'Break problems down and reason about efficiency.',level:'Intermediate → Advanced',icon:'⌁',topics:['Problem decomposition and abstraction','Pseudocode','Linear and binary search','Sorting concepts and basic algorithms','Recursion and base cases','Call-stack behavior','Iteration versus recursion','Time and space complexity','Big O and common complexity classes','Data-structure selection','Practical optimization'],lessons:[
      L('linear-binary-search','Search for values in collections','Linear search checks items one at a time and works on unsorted data. Binary search repeatedly halves the remaining range, but it requires sorted input. Choose the simpler method unless input size or performance requirements justify more complexity.', 'def linear_search(items, target):\n    for index, item in enumerate(items):\n        if item == target:\n            return index\n    return -1\n\nprint(linear_search([8, 3, 5], 5))\nprint(linear_search([8, 3, 5], 9))', '2\n-1', 'The function returns the index of the first match or -1 as a not-found signal. When a collection is large and sorted, binary search can reduce the number of comparisons from linear to logarithmic growth.', 'Write a linear search that returns True if a target is present and False otherwise.', 'def contains(items, target):\n    # check each item\n    pass\n\nprint(contains([2, 4, 6], 4))', 'The answer should be True.', 'Loop through the collection and compare each item to `target`.', 'Return True as soon as a match is found, otherwise return False after the loop.', 'def contains(items, target):\n    for item in items:\n        if item == target:\n            return True\n    return False\n\nprint(contains([2, 4, 6], 4))'),
      L('recursion','Understand recursion and base cases','A recursive function calls itself with a smaller version of the problem. It needs a base case that stops the recursion. Each call uses stack space, so a loop may be more appropriate for simple repeated work.', 'def factorial(n):\n    if n < 0:\n        raise ValueError("n must be non-negative")\n    if n <= 1:\n        return 1\n    return n * factorial(n - 1)\n\nprint(factorial(5))', '120', 'The base case handles zero and one. Every other call decreases `n`, so it moves toward that case. Without a base case or progress toward it, recursion eventually fails with a recursion limit error.', 'Write a recursive function that returns the sum of integers from 1 to n.', 'def sum_to(n):\n    if n <= 0:\n        return 0\n    # combine n with a smaller problem', 'The sum for 4 should be 10.', 'The base case can return 0 for n <= 0.', 'Return `n + sum_to(n - 1)`.', 'def sum_to(n):\n    if n <= 0:\n        return 0\n    return n + sum_to(n - 1)\n\nprint(sum_to(4))'),
      L('big-o','Reason about Big O complexity','Big O describes how an algorithm’s resource use grows as input size grows, ignoring constants and lower-order details. It helps compare approaches, but real performance also depends on data, hardware, memory, and implementation.', 'def print_pairs(items):\n    for first in items:\n        for second in items:\n            print(first, second)\n\nprint("With n items, the nested loop creates n × n pairs.")', 'With n items, the nested loop creates n × n pairs.', 'A single loop over n items is commonly O(n). Two nested loops each ranging over n items are commonly O(n²). Binary search over sorted data is O(log n). Do not optimize blindly: measure and keep correctness tests.', 'For 100 items, how many pairs does the double loop produce? Print the result.', 'n = 100\npairs = ...\nprint(pairs)', 'A double loop considers every ordered pair.', 'Multiply n by n.', 'There are 10,000 pairs.', 'n = 100\npairs = n * n\nprint(pairs)')
    ]},
    {id:'testing-quality',number:15,title:'Testing and Code Quality',subtitle:'Make code more dependable and easier to maintain.',level:'Intermediate → Advanced',icon:'✓',topics:['Assertions and unit tests','unittest and fixtures','Edge cases and regression tests','Test-driven development','Mocking fundamentals','Type hints','PEP 8 and naming','Documentation and code review','Refactoring','Maintainability','Linting and formatting concepts'],lessons:[
      L('assertions-tests','Write assertions and unit tests','Tests make expected behavior executable. An assertion states that a condition should be true; a unit test groups checks into a repeatable verification. Include normal cases, boundary values, and invalid inputs where relevant.', 'def multiply(a, b):\n    return a * b\n\nassert multiply(3, 4) == 12\nassert multiply(0, 9) == 0\nassert multiply(-2, 3) == -6\nprint("All checks passed")', 'All checks passed', 'An assertion raises `AssertionError` when its condition is false. Python can disable ordinary `assert` statements in optimized mode, so do not use them for validating untrusted user input in production.', 'Write a `is_even(number)` function and add assertions for 2 and 5.', 'def is_even(number):\n    return ...\n\nassert is_even(2) is True\nassert is_even(5) is False\nprint("Checks passed")', 'Use remainder to identify even numbers.', 'An even number has remainder zero when divided by 2.', 'Return the boolean expression directly.', 'def is_even(number):\n    return number % 2 == 0\n\nassert is_even(2) is True\nassert is_even(5) is False\nprint("Checks passed")'),
      L('refactoring-pep8','Refactor for clarity and follow conventions','Refactoring changes internal structure without intentionally changing behavior. Descriptive names, small functions, consistent formatting, and straightforward control flow make future changes safer. PEP 8 is the widely used style guide for Python code.', 'def calculate_total(prices):\n    """Return the sum of a sequence of prices."""\n    total = 0\n    for price in prices:\n        total += price\n    return total\n\nprint(calculate_total([10, 15, 5]))', '30', 'A descriptive function and variable name communicate intent. For this specific operation, `sum(prices)` is already clear; keep the longer implementation when teaching the accumulator pattern, and prefer the built-in for production code unless you need extra logic.', 'Refactor a vague function called `f(x)` to a clearer `double(number)` function with a docstring.', 'def double(number):\n    """Return twice a number."""\n    return ...\n\nprint(double(6))', 'The result should be 12.', 'Multiplication is clearer than a long repeated addition.', 'The parameter name should describe the value it represents.', 'def double(number):\n    """Return twice a number."""\n    return number * 2\n\nprint(double(6))'),
      L('edge-regression','Test edge cases and prevent regressions','An edge case is an input at a boundary or unusual point. A regression occurs when a change breaks behavior that used to work. Small automated tests make refactoring safer by rerunning the expectations after each change.', 'def safe_first(items, default=None):\n    if not items:\n        return default\n    return items[0]\n\nassert safe_first(["a", "b"]) == "a"\nassert safe_first([]) is None\nassert safe_first([], "empty") == "empty"\nprint("Edge cases checked")', 'Edge cases checked', 'Empty input deserves an explicit test because indexing an empty list would raise `IndexError`. Also test optional defaults and types that the function is expected to accept.', 'Write `safe_divide(a, b)` that returns None if b is zero, otherwise returns a divided by b.', 'def safe_divide(a, b):\n    if b == 0:\n        return None\n    return ...', 'Test both a normal denominator and zero.', 'Use a guard clause for zero.', 'For all other values, use `/`.', 'def safe_divide(a, b):\n    if b == 0:\n        return None\n    return a / b\n\nprint(safe_divide(9, 3))')
    ]},
    {id:'concurrency',number:16,title:'Concurrency and Asynchronous Python',subtitle:'Understand tasks, threads, processes, and async I/O.',level:'Advanced',icon:'⇄',topics:['Blocking and non-blocking operations','Processes and threads','threading and multiprocessing','async and await','Coroutines, event loops, tasks','Asynchronous I/O','Race conditions and synchronization','Shared state','Concurrency versus parallelism'],browserNote:'The concepts and most pure-Python demonstrations run here, but creating operating-system processes, controlling native threads, or performing real system I/O can be limited by the browser runtime. Use ordinary local Python for full OS concurrency experiments.',lessons:[
      L('async-await','Understand async and await','Asynchronous functions use `async def`; calling one produces a coroutine object. `await` gives the event loop a chance to run other ready tasks while an awaitable is waiting. Async is especially useful for high-latency I/O, not automatically faster for CPU-heavy calculations.', 'import asyncio\n\nasync def greet(name):\n    await asyncio.sleep(0)\n    return f"Hello, {name}!"\n\nasync def main():\n    message = await greet("Mina")\n    print(message)\n\nawait main()', 'Hello, Mina!', 'Pyodide’s `runPythonAsync()` supports top-level await, which is used by this playground. Native event-loop integration and some async libraries may behave differently from a local CPython application, so verify environment-specific code before relying on it.', 'Create an async function `double_after_tick(n)` that awaits `asyncio.sleep(0)` and returns twice n.', 'import asyncio\n\nasync def double_after_tick(n):\n    await asyncio.sleep(0)\n    return ...\n\nprint(await double_after_tick(5))', 'The output should be 10.', 'Use `return n * 2` after the await.', 'Call it with `await`.', 'import asyncio\n\nasync def double_after_tick(n):\n    await asyncio.sleep(0)\n    return n * 2\n\nprint(await double_after_tick(5))'),
      L('threads-processes','Choose threads or processes thoughtfully','Threads share one process and its memory; processes have separate address spaces. Threads can be helpful for overlapping I/O. Processes can run CPU work in parallel when the environment permits it. Starting processes is generally not supported in the browser runtime.', 'tasks = ["download", "wait for response", "parse result"]\nprint("An I/O workflow can spend much of its time waiting.")\nprint("A browser runtime does not provide unrestricted local process creation.")\nprint("Steps:", len(tasks))', 'An I/O workflow can spend much of its time waiting.\nA browser runtime does not provide unrestricted local process creation.\nSteps: 3', 'Pick concurrency based on the bottleneck and shared-state requirements. Shared mutable state needs coordination to avoid race conditions. In a real local project, consult module-specific documentation and test how threads or processes behave on the target platform.', 'List three tasks that could wait on network responses, and print their count.', 'tasks = ["fetch profile", "fetch courses", "fetch scores"]\nprint(len(tasks))', 'This exercise practices decomposition without starting OS threads or processes.', 'Use `len()` to count the entries.', 'Keep each task as a separate list item.', 'tasks = ["fetch profile", "fetch courses", "fetch scores"]\nprint(len(tasks))'),
      L('race-conditions','Recognize shared-state risks','A race condition occurs when the outcome depends on the timing or interleaving of operations. Locks, queues, immutable data, or single-owner designs can help protect shared state. The simplest fix is often to reduce how much mutable state is shared.', 'balance = 100\nwithdrawals = [30, 25]\nfor amount in withdrawals:\n    if amount <= balance:\n        balance -= amount\nprint(balance)', '45', 'The example is sequential, so operations happen in a known order. In concurrent code, a check followed by an update can be interrupted by another task unless the operation is coordinated. Do not infer that one successful sequential test proves thread safety.', 'Simulate two sequential withdrawals from a balance and prevent the balance from becoming negative.', 'balance = 50\nfor amount in [30, 30]:\n    # validate and withdraw', 'Only the first 30-unit withdrawal should succeed.', 'Check the amount before subtracting it.', 'Add a helpful branch for a withdrawal that cannot be completed.', 'balance = 50\nfor amount in [30, 30]:\n    if amount <= balance:\n        balance -= amount\n    else:\n        print("Insufficient funds")\nprint(balance)')
    ]},
    {id:'application-dev',number:17,title:'Application Development',subtitle:'Bring Python programs into real-world workflows.',level:'Intermediate → Advanced',icon:'⚙',topics:['Command-line applications','Input validation and configuration','Logging','HTTP fundamentals and APIs','JSON responses','Database fundamentals and SQL','SQLite','Application organization','Environment variables','Credential protection','Security fundamentals','Deployment concepts','Performance measurement'],browserNote:'The browser sandbox does not expose unrestricted subprocesses, local environment settings, or system access. This module teaches the ideas and runnable pure-Python examples; follow the local setup path for real APIs, databases, and deployments.',lessons:[
      L('http-json','Understand APIs and JSON','An API exposes an interface for software to exchange data. An HTTP API commonly uses methods such as GET and POST, status codes, headers, and structured response bodies. JSON is a common format for exchanging records between systems.', 'import json\n\nresponse_text = \'{"status": "ok", "count": 3}\'\nresponse = json.loads(response_text)\nprint(response["status"])\nprint(response["count"])', 'ok\n3', 'This example parses a response-like string but does not make a network request. Real applications should handle transport errors, non-success status codes, timeouts, invalid JSON, and data validation.', 'Parse the JSON string `{"city":"Lahore","days":4}` and print the city.', 'import json\ntext = \'{"city":"Lahore","days":4}\'\ndata = ...\nprint(data["city"])', 'The result should be Lahore.', 'Use `json.loads(text)`.', 'The returned value is a dictionary.', 'import json\ntext = \'{"city":"Lahore","days":4}\'\ndata = json.loads(text)\nprint(data["city"])'),
      L('sqlite-design','Store structured records with SQLite','SQLite is a lightweight relational database stored in a file. SQL queries select, insert, update, and delete rows in tables. Use parameterized queries rather than building SQL by concatenating untrusted user input.', 'import sqlite3\n\nconnection = sqlite3.connect(":memory:")\nconnection.execute("CREATE TABLE tasks (title TEXT, done INTEGER)")\nconnection.execute("INSERT INTO tasks VALUES (?, ?)", ("Practice", 0))\nrows = connection.execute("SELECT title, done FROM tasks").fetchall()\nprint(rows)\nconnection.close()', "[('Practice', 0)]", 'The `?` placeholders keep values separate from SQL syntax, reducing SQL injection risk. The `:memory:` database lives only in the current process and is useful for repeatable practice.', 'Create an in-memory table for products, insert one product with a parameterized query, and select its name.', 'import sqlite3\nconnection = sqlite3.connect(":memory:")\n# create table, insert row, select name\nconnection.close()', 'A table needs a text column for the product name.', 'Use `CREATE TABLE products (name TEXT)`.', 'Insert with `VALUES (?)` and a one-item tuple.', 'import sqlite3\nconnection = sqlite3.connect(":memory:")\nconnection.execute("CREATE TABLE products (name TEXT)")\nconnection.execute("INSERT INTO products VALUES (?)", ("Notebook",))\nprint(connection.execute("SELECT name FROM products").fetchone())\nconnection.close()'),
      L('config-secrets','Protect credentials and configure applications','Configuration varies between machines, so keep deployment-specific values out of source code. Environment variables are a common local/server configuration mechanism, but any secret embedded in frontend JavaScript is visible to visitors. Never put private API keys in this static website.', 'required_settings = ["API endpoint", "timeout", "feature flag"]\nfor setting in required_settings:\n    print(f"Document configuration value: {setting}")\nprint("Never commit private credentials.")', 'Document configuration value: API endpoint\nDocument configuration value: timeout\nDocument configuration value: feature flag\nNever commit private credentials.', 'A static browser application cannot keep a secret from the person running the browser. A service that needs a private key generally requires a protected server-side component. The core PyTrail site intentionally uses no API key.', 'Define a settings dictionary with a request timeout and a feature flag, then print it.', 'settings = {"timeout_seconds": 10, "feature_enabled": True}\nprint(settings)', 'This example practices structured configuration without exposing secrets.', 'Use numbers and booleans for values that are not text.', 'Access a setting with its key when you need a single value.', 'settings = {"timeout_seconds": 10, "feature_enabled": True}\nprint(settings["timeout_seconds"])')
    ]},
    {id:'specializations',number:18,title:'Specialization Paths',subtitle:'Choose a direction and build a focused skill set.',level:'Exploration',icon:'◇',topics:['Automation and scripting','Data analysis with NumPy and pandas','Web development','AI and machine learning fundamentals','Game development','Competitive programming','Professional Python development','Third-party library requirements and local installs'],browserNote:'Specialist packages vary in Pyodide support. Standard Python exercises run in this site; libraries such as NumPy may be available in supported versions, but not every native extension or package works. Use the local setup guide for full ecosystem compatibility.',lessons:[
      L('automation-planning','Plan reliable automation scripts','Automation scripts replace repeatable manual work. Before coding, define the input, output, error cases, and how you will know the task succeeded. Use dry-run modes for destructive actions such as moving or deleting files.', 'files = ["report.csv", "notes.txt", "image.png"]\ntext_files = [name for name in files if name.endswith(".txt")]\nprint(text_files)\nprint("Plan and preview file changes before applying them.")', "['notes.txt']\nPlan and preview file changes before applying them.", 'This example filters names without touching the real filesystem. A real organizer should consider nested folders, name conflicts, backups, permissions, and a dry-run preview before renaming files.', 'Filter a list of filenames to include only those ending with `.csv`.', 'files = ["sales.csv", "notes.txt", "data.csv"]\n# filter csv files\nprint(csv_files)', 'The result should contain sales.csv and data.csv.', 'Use `endswith(".csv")`.', 'A list comprehension is enough for this small task.', 'files = ["sales.csv", "notes.txt", "data.csv"]\ncsv_files = [name for name in files if name.endswith(".csv")]\nprint(csv_files)'),
      L('data-ai-path','Map a data and AI learning path','Data workflows often move through collection, cleaning, exploration, visualization, modeling, and evaluation. NumPy provides array operations; pandas offers labelled tabular data. Machine-learning libraries add concepts such as training data, features, targets, metrics, and generalization.', 'records = [\n    {"name": "A", "score": 84},\n    {"name": "B", "score": 91},\n    {"name": "C", "score": 76},\n]\naverage_score = sum(row["score"] for row in records) / len(records)\nprint(round(average_score, 1))', '83.7', 'You can learn many data concepts with the standard library first. Then try NumPy or pandas on local Python or a compatible browser runtime. Do not train or evaluate a model on the same data without considering data leakage.', 'Calculate the highest score from the sample records.', 'records = [{"score": 84}, {"score": 91}, {"score": 76}]\n# find the highest score', 'The maximum score is 91.', 'Extract the score value from each dictionary.', 'The built-in `max()` works with the extracted scores.', 'records = [{"score": 84}, {"score": 91}, {"score": 76}]\nprint(max(row["score"] for row in records))'),
      L('web-game-path','Explore web services and game projects','Python web frameworks can build APIs and server-rendered applications; game libraries such as Pygame provide a local window and event loop. These projects need a local Python setup and dependencies that are not guaranteed to work in the browser playground.', 'project_plan = {\n    "goal": "Build a small quiz API",\n    "skills": ["functions", "JSON", "testing", "HTTP"],\n    "first_milestone": "Return one hard-coded question",\n}\nprint(project_plan["first_milestone"])', 'Return one hard-coded question', 'Start with one vertical slice: implement a small feature end to end, test it, and then expand. Keep keys outside the repository and review dependency support before choosing a framework.', 'Create a three-item milestone list for your next Python project and print the first milestone.', 'milestones = ["plan", "build", "test"]\nprint(...)', 'List indexing starts at zero.', 'Use `milestones[0]`.', 'The first item is the planning step.', 'milestones = ["plan", "build", "test"]\nprint(milestones[0])')
    ]},
    {id:'capstones',number:19,title:'Capstone Projects',subtitle:'Apply your skills to complete, testable programs.',level:'All levels',icon:'🚀',topics:['Personalized greeting','Calculator','Number guessing game','Multiplication table generator','Quiz application','Password-strength checker','Unit converter','To-do list','Contact book','Text analyzer','Expense tracker','File organizer','JSON notes application','Student grade manager','OOP library model','CSV data analyzer','SQLite inventory manager','Log-file analyzer','Command-line productivity utility','Comprehensive capstone'],lessons:[
      L('project-planning','Plan a project before writing code','Projects combine concepts rather than introduce one new syntax feature at a time. Start with a small statement of purpose, split requirements into milestones, and decide how you will test each milestone before implementing everything.', 'requirements = [\n    "Add a task",\n    "List tasks",\n    "Mark a task complete",\n    "Keep the interface understandable",\n]\nfor index, requirement in enumerate(requirements, start=1):\n    print(f"Milestone {index}: {requirement}")', 'Milestone 1: Add a task\nMilestone 2: List tasks\nMilestone 3: Mark a task complete\nMilestone 4: Keep the interface understandable', 'A clear checklist gives you a stopping point and helps avoid building a large program before confirming the basic flow works. Implement and test one milestone at a time.', 'Choose a project and write three small milestones before coding it.', 'project = "To-do list"\nmilestones = ["...", "...", "..."]\nprint(project)\nfor item in milestones:\n    print(item)', 'Replace each placeholder with a concrete, testable goal.', 'Make the first milestone the smallest useful version.', 'Avoid vague milestones such as “make it good”. State what the program should do.', 'project = "To-do list"\nmilestones = ["Add one task", "List all tasks", "Mark one task complete"]\nprint(project)\nfor item in milestones:\n    print(item)'),
      L('project-testing','Test and improve a project in small steps','A finished project is more than code that runs once. Verify normal behavior, boundary cases, invalid input, saved data, and failure messages. Leave the project in a state where another person can understand how to start it.', 'def convert_celsius_to_fahrenheit(celsius):\n    return celsius * 9 / 5 + 32\n\nassert convert_celsius_to_fahrenheit(0) == 32\nassert convert_celsius_to_fahrenheit(100) == 212\nprint("Project smoke tests passed")', 'Project smoke tests passed', 'These two assertions cover useful known values. Strong projects also test values between boundaries, input validation, and the expected behavior after errors.', 'Write two tests for a unit converter, then add a helpful README instruction.', 'def km_to_miles(km):\n    return km * 0.621371\n\n# add an assertion and a run instruction', 'A zero-kilometre input should result in zero miles.', 'Test a second familiar conversion too.', 'A README should tell a beginner how to start and what the program does.', 'def km_to_miles(km):\n    return km * 0.621371\n\nassert km_to_miles(0) == 0\nassert round(km_to_miles(1), 2) == 0.62\nprint("Run: python converter.py")'),
      L('capstone-review','Review and present your capstone','A capstone should demonstrate a coherent purpose, readable structure, error handling, and tests. Briefly describe the problem, how to run the program, decisions you made, known limitations, and the next improvement you would make.', 'review = {\n    "purpose": "Help track small tasks",\n    "tested": True,\n    "known_limitations": ["local-only data", "no reminders"],\n    "next_improvement": "export tasks as JSON",\n}\nprint(review["purpose"])\nprint("Ready to present:", review["tested"])', 'Help track small tasks\nReady to present: True', 'Honest limitations make a project more credible, not less. Explain which features are complete, what was tested, and what remains. An improvement backlog helps you choose the next step.', 'Write a brief project summary and one future improvement in a dictionary.', 'summary = {"project": "...", "future_improvement": "..."}\nprint(summary)', 'Use clear, concrete phrases instead of generic descriptions.', 'The project field names can be anything meaningful.', 'Keep the summary concise and describe a real behavior.', 'summary = {"project": "A quiz with scored questions", "future_improvement": "Save results to JSON"}\nprint(summary)')
    ]}
  ];

  // Normalize metadata so the UI and progress engine have stable IDs and consistent relationships.
  const lessons = [];
  modules.forEach(module => {
    module.lessons.forEach((lesson, index) => {
      lesson.moduleId = module.id;
      lesson.moduleTitle = module.title;
      lesson.moduleNumber = module.number;
      lesson.lessonNumber = index + 1;
      lesson.totalInModule = module.lessons.length;
      lesson.level = module.level;
      lesson.keyTopics = module.topics;
      lessons.push(lesson);
    });
  });
  window.PYTRAIL_CURRICULUM = modules;
  window.PYTRAIL_LESSONS = lessons;
})();
